'use strict';
(() => {
 const D=window.PORTFOLIO, $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const state={category:'career',company:'all',group:'all',project:null}, localImages=new Map();
 const projectDialog=$('#project-dialog'), imageDialog=$('#image-dialog');
 let currentId=null,returnFocus=null,toastTimer;
 function safeUrl(value,allowBlob=false){if(!value)return '';try{const u=new URL(value,location.href);return ['http:','https:'].includes(u.protocol)||(allowBlob&&u.protocol==='blob:')?u.href:''}catch{return ''}}
 function route(project=null){return '#/'+[state.category,state.company,state.group,...(project?[project]:[])].map(encodeURIComponent).join('/')}
 function setRoute(){history.pushState(null,'',route());readRoute()}
 function status(p){return `<span class="status ${p.status==='draft'?'draft':''}">${p.status==='draft'?'세부 자료 작성 예정':'업무·이력 기록'}</span>`}
 function mainTabs(){ $('#main-tabs').innerHTML=D.categories.map(c=>`<button id="tab-${c.id}" role="tab" aria-selected="${state.category===c.id}" aria-controls="portfolio-panel" tabindex="${state.category===c.id?0:-1}" data-category="${c.id}">${esc(c.label)}<small>${String(D.projects.filter(p=>p.category===c.id).length).padStart(2,'0')}</small></button>`).join('');$('#portfolio-panel').setAttribute('aria-labelledby','tab-'+state.category); }
 function renderList(){mainTabs();const c=D.categories.find(c=>c.id===state.category);let projects=D.projects.filter(p=>p.category===state.category);$('#filters').innerHTML='';if(state.category==='career'){$('#filters').innerHTML=`<div class="filter-row" role="group" aria-label="경력 구분">${D.groups.map(g=>`<button data-company="${g.id}" aria-pressed="${state.company===g.id}">${esc(g.label)}</button>`).join('')}</div>`;if(state.company!=='all')projects=projects.filter(p=>p.company===state.company);if(state.company==='hackers'){$('#filters').insertAdjacentHTML('beforeend',`<div class="filter-row sub" role="group" aria-label="해커스 하위 영역">${D.subgroups.map(g=>`<button data-group="${g.id}" aria-pressed="${state.group===g.id}">${esc(g.label)}</button>`).join('')}</div>`);if(state.group!=='all')projects=projects.filter(p=>p.group===state.group);}}
 $('#category-intro').innerHTML=`<div><h3>${esc(c.intro)}</h3><p>${esc(c.description)}</p></div><span>${String(projects.length).padStart(2,'0')} STORIES / ${c.en}</span>`;
 const words={career:['DATA!','TEST!','WHY?','ACTION!'],experience:['TOGETHER','LEAD!','CONNECT'],certificates:['LEARN!','SQL','GROW'],awards:['IDEA!','CREATE!'],volunteer:['WITH!','SHARE'],education:['LEARN!','BUILD!']};
 $('#cards').innerHTML=projects.map((p,i)=>{const src=safeUrl(p.images?.[0]?.src),w=words[p.category];return `<button class="project-card" data-project="${esc(p.id)}" aria-label="${esc(p.title.replace(/\n/g,' '))} 상세 보기"><div class="card-cover"><span class="card-index">CASE ${String(i+1).padStart(2,'0')}</span><span class="cover-corner" aria-hidden="true">✺</span><span class="cover-word" aria-hidden="true">${w[i%w.length]}</span>${src?`<img src="${esc(src)}" alt="${esc(p.images[0].alt)}" loading="lazy">`:''}</div><div class="card-body"><span class="card-tag">${esc(p.tag)}</span><h3>${esc(p.title)}</h3><p>${esc(p.summary)}</p><div class="card-bottom">${status(p)}<span class="card-arrow" aria-hidden="true">↗</span></div></div></button>`}).join('');
 }
 function metricChart(m){if(![m.before,m.after].every(v=>typeof v==='number'&&Number.isFinite(v)&&v>=0)||!m.source||!m.periodBefore||!m.periodAfter)return '';const max=Math.max(m.before,m.after,1);return `<div class="metric"><h4>${esc(m.label)}</h4><div class="metric-row"><span>변경 전</span><div class="metric-bar" style="width:${m.before/max*100}%"></div><b>${esc(m.before)}${esc(m.unit)}</b></div><div class="metric-row"><span>변경 후</span><div class="metric-bar" style="width:${m.after/max*100}%"></div><b>${esc(m.after)}${esc(m.unit)}</b></div><p class="metric-caption">전: ${esc(m.periodBefore)} / 후: ${esc(m.periodAfter)}<br>출처: ${esc(m.source)} · ${esc(m.note||'전후 변화이며 인과관계를 의미하지 않습니다.')}</p></div>`}
 function gallery(p){const imgs=[...(p.images||[]),...(localImages.get(p.id)||[])];return imgs.map((im,i)=>{const src=safeUrl(im.src,true);return `<figure>${src?`<button class="image-button" data-image="${i}" aria-label="${esc(im.alt)} 확대"><img src="${esc(src)}" alt="${esc(im.alt)}" loading="lazy"></button>`:`<div class="image-slot"><b aria-hidden="true">＋</b><span>${esc(im.caption||'이미지 추가 예정')}</span></div>`}<figcaption>${esc(im.caption)}</figcaption></figure>`}).join('')}
 function showProject(p){currentId=p.id;$('#share-row').hidden=true;const learning=['certificates','education'].includes(p.category),a=learning?'학습 목표 및 도전 과제':'문제 발견 및 원인 분석',b=learning?'준비 · 실행 과정 및 TEST':'해결 과정 및 TEST',c=learning?'성취 결과 및 인사이트':'결과 및 인사이트';const logo=safeUrl(D.companies[p.company]?.src);
 $('#detail-content').innerHTML=`<div class="detail-head">${logo?`<img class="detail-logo" src="${esc(logo)}" alt="${esc(D.companies[p.company].alt)}">`:''}<span class="eyebrow">${esc(p.tag)}</span><h2 id="detail-title" tabindex="-1">${esc(p.title)}</h2>${status(p)}<div class="detail-meta"><p><strong>담당 역할</strong> · ${esc(p.role)}</p>${p.period?`<p><strong>기간 / 일자</strong> · ${esc(p.period)}</p>`:''}${p.issuer?`<p><strong>발급 기관</strong> · ${esc(p.issuer)}</p>`:''}</div><div class="skills">${(p.tools||[]).map(t=>`<span>${esc(t)}</span>`).join('')}</div><nav class="process-nav" aria-label="문제 해결 단계"><a href="#step-problem" data-step="step-problem">01 문제 · 목표</a><a href="#step-solution" data-step="step-solution">02 해결 · TEST</a><a href="#step-result" data-step="step-result">03 결과 · 배움</a></nav></div><section id="step-problem" class="detail-step"><div class="step-heading"><span>01</span><div><small>PROBLEM / ANALYSIS</small><h3>${a}</h3></div></div><div class="step-body"><p>${esc(p.problem)}</p><h4>배경과 원인 · 가설</h4><p>${esc(p.cause)}</p></div></section><section id="step-solution" class="detail-step solution-step"><div class="step-heading"><span>02</span><div><small>SOLUTION / ACTION</small><h3>${b}</h3></div></div><div class="step-body"><ol>${p.solution.map(s=>`<li>${esc(s)}</li>`).join('')}</ol><div class="test-box"><h4>TEST & VALIDATION</h4><p>${esc(p.test)}</p></div></div></section><section id="step-result" class="detail-step"><div class="step-heading"><span>03</span><div><small>RESULT / INSIGHT</small><h3>${c}</h3></div></div><div class="step-body"><p>${esc(p.result)}</p>${(p.metrics||[]).map(metricChart).join('')}<div class="insight"><strong>WHAT I LEARNED ↗</strong><p>${esc(p.insight)}</p></div></div></section><section class="evidence-section"><span class="eyebrow">EVIDENCE & PROCESS</span><h3>과정을 보여주는 자료</h3><p>이미지를 누르면 확대할 수 있습니다. 증빙은 공개 가능한 자료만 사용합니다.</p><div class="gallery">${gallery(p)}</div>${(p.evidence||[]).filter(e=>safeUrl(e.url)).map(e=>`<p><a href="${esc(safeUrl(e.url))}" target="_blank" rel="noopener noreferrer">${esc(e.label)} ↗</a></p>`).join('')}<details class="preview-tools"><summary>내 이미지로 미리보기</summary><p>선택한 이미지는 현재 브라우저 메모리에서만 표시됩니다. 서버에 업로드되지 않으며 새로고침하면 사라집니다. 실제 반영은 data.js와 저장소 이미지 수정 후 재배포가 필요합니다.</p><label>이미지 선택 (여러 장 가능 · 장당 10MB 이하)<input id="preview-files" type="file" accept="image/png,image/jpeg,image/webp,image/gif" multiple></label><button id="clear-preview">임시 이미지 지우기</button><p id="preview-status" role="status"></p></details></section>`;
 if(!projectDialog.open){returnFocus=document.activeElement;projectDialog.showModal();}projectDialog.scrollTop=0;$('#detail-title').focus({preventScroll:true});document.title=p.title.replace(/\n/g,' ')+' | 공재성 포트폴리오';
 }
 function closeProject(){if(location.hash.startsWith('#/')){history.pushState(null,'',route());readRoute();}else if(projectDialog.open)projectDialog.close()}
 function readRoute(){let parts=[];try{parts=location.hash.slice(2).split('/').map(decodeURIComponent)}catch{};if(location.hash.startsWith('#/')){state.category=D.categories.some(c=>c.id===parts[0])?parts[0]:'career';state.company=D.groups.some(g=>g.id===parts[1])?parts[1]:'all';state.group=D.subgroups.some(g=>g.id===parts[2])?parts[2]:'all';if(state.category!=='career'){state.company='all';state.group='all'}if(state.company!=='hackers')state.group='all';}
 renderList();const p=location.hash.startsWith('#/')?D.projects.find(p=>p.id===parts[3]&&p.category===state.category):null;
 if(p)showProject(p);else{currentId=null;if(imageDialog.open)imageDialog.close();if(projectDialog.open){projectDialog.close();const id=returnFocus?.dataset?.project;const target=id?$(`[data-project="${CSS.escape(id)}"]`):returnFocus;if(target?.isConnected)target.focus({preventScroll:true});}document.title='공재성 — 데이터를 읽고, 실행으로 답하다';if(parts[3])toast('요청한 사례를 찾을 수 없어 목록을 표시합니다.');}}
 function toast(t){$('#toast').textContent=t;$('#toast').classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),3000)}
 document.addEventListener('click',async e=>{const el=e.target.closest('button,a');if(!el)return;
 if(el.dataset.category){const id=el.dataset.category;state.category=id;state.company='all';state.group='all';setRoute();$('#tab-'+id)?.focus({preventScroll:true})}
 if(el.dataset.company){state.company=el.dataset.company;state.group='all';setRoute()}
 if(el.dataset.group){state.group=el.dataset.group;setRoute()}
 if(el.dataset.project){history.pushState(null,'',route(el.dataset.project));readRoute()}
 if(el.dataset.step){e.preventDefault();$('#'+el.dataset.step).scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth',block:'start'})}
 if(el.id==='close-button'||el.id==='back-button')closeProject();
 if(el.id==='share-button'){$('#share-row').hidden=false;$('#share-url').value=location.href;$('#share-url').focus();$('#share-url').select();toast('공유 주소를 표시했습니다.');if(navigator.clipboard)navigator.clipboard.writeText(location.href).then(()=>toast('이 사례의 링크를 복사했습니다.')).catch(()=>toast('선택된 공유 주소를 복사해 주세요.'));}
 if(el.dataset.image!==undefined){const p=D.projects.find(p=>p.id===currentId),im=[...(p.images||[]),...(localImages.get(p.id)||[])][Number(el.dataset.image)];$('#large-image').src=safeUrl(im.src,true);$('#large-image').alt=im.alt;$('#large-caption').textContent=im.caption;imageDialog.showModal()}
 if(el.id==='image-close')imageDialog.close();
 if(el.id==='clear-preview'){for(const im of localImages.get(currentId)||[])URL.revokeObjectURL(im.src);localImages.delete(currentId);$('.gallery').innerHTML=gallery(D.projects.find(p=>p.id===currentId));$('#preview-files').value='';$('#preview-status').textContent='임시 이미지를 지웠습니다.'}
 });
 $('#main-tabs').addEventListener('keydown',e=>{if(!['ArrowRight','ArrowLeft','Home','End'].includes(e.key))return;e.preventDefault();const tabs=[...$('#main-tabs').querySelectorAll('button')];let i=tabs.findIndex(b=>b===document.activeElement);if(e.key==='Home')i=0;else if(e.key==='End')i=tabs.length-1;else i=(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[i].click()});
 document.addEventListener('change',e=>{if(e.target.id!=='preview-files')return;let accepted=0,rejected=0;const list=localImages.get(currentId)||[];for(const file of e.target.files){if(!['image/png','image/jpeg','image/webp','image/gif'].includes(file.type)||file.size>10*1024*1024){rejected++;continue}list.push({src:URL.createObjectURL(file),alt:file.name,caption:'임시 미리보기 · '+file.name});accepted++;}localImages.set(currentId,list);$('.gallery').innerHTML=gallery(D.projects.find(p=>p.id===currentId));$('#preview-status').textContent=`${accepted}장 추가됨${rejected?` · 지원하지 않는 형식 또는 10MB 초과 ${rejected}장 제외`:''}. 새로고침하면 사라집니다.`;e.target.value=''});
 document.addEventListener('error',e=>{if(e.target.tagName!=='IMG')return;const parent=e.target.closest('.image-button');if(parent){const box=document.createElement('div');box.className='image-slot';box.textContent='이미지를 불러오지 못했습니다. 경로를 확인해 주세요.';parent.replaceWith(box)}else e.target.hidden=true},true);
 projectDialog.addEventListener('cancel',e=>{e.preventDefault();closeProject()});projectDialog.addEventListener('click',e=>{if(e.target===projectDialog){const r=projectDialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeProject()}});
 imageDialog.addEventListener('click',e=>{if(e.target===imageDialog)imageDialog.close()});
 const profileSrc=safeUrl(D.profile.src);$('#profile-image').innerHTML=profileSrc?`<img src="${esc(profileSrc)}" alt="${esc(D.profile.alt)}">`:'<div class="profile-placeholder"><b>J.K</b><span>PROFILE IMAGE<br>프로필 사진 추가 예정</span></div>';
 if(!matchMedia('(prefers-reduced-motion: reduce)').matches){const observer=new IntersectionObserver(entries=>{entries.forEach(e=>{if(e.isIntersecting){e.target.classList.add('reveal');observer.unobserve(e.target)}})},{threshold:.12});document.querySelectorAll('.section-heading,.about-title,.contact-section h2').forEach(e=>observer.observe(e));$('.hero').addEventListener('pointermove',e=>{if(e.pointerType!=='mouse')return;const r=$('.hero').getBoundingClientRect();$('.hero-art').style.setProperty('--mx',((e.clientX-r.left)/r.width-.5)*8+'px');$('.hero-art').style.setProperty('--my',((e.clientY-r.top)/r.height-.5)*8+'px')});$('.hero').addEventListener('pointerleave',()=>{$('.hero-art').style.setProperty('--mx','0px');$('.hero-art').style.setProperty('--my','0px')})}
 window.addEventListener('hashchange',readRoute);readRoute();
})();
